local UIEventProxy = CS.Engine.UI.UIEventProxy
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local URPCameraController = CS.Game.Native.URP.URPCameraController.Instance
local ScreenPointToLocalPointInRectangle = CS.UnityEngine.RectTransformUtility.ScreenPointToLocalPointInRectangle
local CanvasGroup = CS.UnityEngine.CanvasGroup

------------ import ------------

------------ define ------------
local offsetPos = Vector3(0, 0, 0)
local headScale = {
    small = 0.7,
    large = 1,
}
local targetNodeScale = {
    small = 0.8 * 0.65,
    large = 0.8,
}
------------ define ------------


---@class DirectionalHeadNode
---@field TxtNum                        	TMPro.TextMeshProUGUI
---@field RoundsGroup                   	UnityEngine.RectTransform
---@field TxtTime                       	UnityEngine.UI.Text
---@field LockTime                      	UnityEngine.RectTransform
---@field Mask                          	UnityEngine.RectTransform
---@field TxtDebris                     	Game.Native.Common.UISwitchText
---@field HeadIcon                      	Engine.UI.ImageAlterable
---@field HeadFrame                     	Game.Native.Common.UISwitchImage
---@field BtnHeadGroup                  	UnityEngine.RectTransform
---@field HeadItem                      	Engine.Lib.BehaviourAction
local DirectionalHeadNode = Class("DirectionalHeadNode")
function DirectionalHeadNode:__init()
    self.btnAction = nil
    self.targetNode = nil--在Update中位置跟随的目标物体
    self.camera = nil--在Update中位置跟随的目标相机
end

function DirectionalHeadNode:__delete()
    self.btnAction = nil
    self.targetNode = nil
    self.camera = nil

    self.controller = nil
end

function DirectionalHeadNode:SetBtnCallBack(cb)
    self.btnAction = cb

end

function DirectionalHeadNode:Awake()
    SetButtonAction(self.BtnHeadGroup, function ()
        if type(self.btnAction) == 'function' then
            self.btnAction()
        end
    end)
    self.HeadItem.UpdateAction = function()
        self:OnUpdate()
    end
end

function DirectionalHeadNode:FreshBaseUI(data)
    local isOpen = checkNumber(data.isOpen) == 1
    KTool.SetActive(self.LockTime, not isOpen)
    KTool.SetActive(self.RoundsGroup, isOpen)
    --self.HeadFrame.Status = checkNumber(data.type)
    self.HeadIcon:LoadSprite(data.iconPath)
    --self.TxtDebris.Status = checkNumber(data.type)
    --KTool.SetActive(self.Mask, not isOpen)
    local uiLocalize = self.TxtTime:GetComponent(typeof(CS.Engine.Lib.UILocalize))
    uiLocalize.Key = nil   --UILocalize在awake时会通过key设置text,覆盖代码里的修改
    self.TxtTime.text = data.openTime
    --self.TxtDebris.transform.parent.gameObject:EnsureComponent(typeof(CanvasGroup)).alpha = isOpen and 1 or 0.15

    if isOpen then
        self.TxtNum.text = data.winTime
    end
    local scale = data.isFirst and headScale.large or headScale.small
    self.controller.transform.localScale = Vector3.New(scale, scale , scale)
    local targetNodeScale = data.isFirst and targetNodeScale.large or targetNodeScale.small
    self.targetNode.transform.localScale = Vector3.New(targetNodeScale, targetNodeScale , targetNodeScale)
end

function DirectionalHeadNode:SetTargetNode(targetNode, camera)
    self.targetNode = targetNode
    self.camera = camera
    --printInfo("targetNode===="..self.camera.name)
end

---设置选中和未选中的缩放的动画
function DirectionalHeadNode:SetSelectedScale(isSelected)
    local scale = isSelected and headScale.large or headScale.small
    self.controller.transform:DOScale(scale, 0.5)
    local targetNodeScale = isSelected and targetNodeScale.large or targetNodeScale.small
    self.targetNode.transform:DOScale(targetNodeScale, 0.5)
end

---BehaviourAction的Update方法
function DirectionalHeadNode:OnUpdate()
    if isNull(self.targetNode) then
        return
    end
    local pos = CfUtils.WorldPosition2UIPosition(self.targetNode.transform.position,  self.controller.transform.parent.transform)
    self.controller.transform.anchoredPosition = Vector3(pos.x, pos.y, 0) + offsetPos
end

function DirectionalHeadNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return DirectionalHeadNode